import { useState } from 'react'
import { Helmet } from 'react-helmet-async'
import { useNavigate } from 'react-router'

import { Box, Button, Card, Chip, Container, Stack, Typography, useMediaQuery, useTheme } from '@mui/material'
import type { GridColDef, GridRenderCellParams } from '@mui/x-data-grid'
import { DataGrid } from '@mui/x-data-grid'

import { DEFAULT_DELETE_MESSAGE } from 'src/data/cofirmDialogueMessages'
import { PARTNER_COUPON_STATUS_LABELS } from 'src/data/partnerBenefits'

import { formatPartnerBenefitDate } from 'src/utils/partnerBenefits'

import ConfirmDialog from 'src/components/ConfirmDialog'
import PageTitleWrapper from 'src/components/PageTitleWrapper'

import { usePartnerBenefits } from 'src/hooks/usePartnerBenefits'

interface CouponTableRow {
  id: number
  storeId: number
  storeName: string
  benefitContent: string
  period: string
  status: string
  createdAt: string
}

interface DeleteTargetCoupon {
  couponId: number
  storeId: number
}

const BenefitCouponManagePage: React.FC = () => {
  const theme = useTheme()
  const isMobile = useMediaQuery(theme.breakpoints.down('sm'))
  const navigate = useNavigate()
  const { stores, coupons, deletePartnerCoupon } = usePartnerBenefits({ mode: 'admin' })
  const [deleteTargetCoupon, setDeleteTargetCoupon] = useState<DeleteTargetCoupon | null>(null)

  const activeStores = stores.filter(store => !store.deletedAt)
  const activeCoupons = coupons.filter(coupon => !coupon.deletedAt)
  const couponRows: CouponTableRow[] = activeCoupons.map(coupon => {
    const store = activeStores.find(store => store.id === coupon.partnerStoreId)
    return {
      id: coupon.id,
      storeId: coupon.partnerStoreId,
      storeName: store?.name ?? '삭제된 가게',
      benefitContent: coupon.benefitContent,
      period: `${formatPartnerBenefitDate(coupon.startDate)} ~ ${formatPartnerBenefitDate(coupon.endDate)}`,
      status: PARTNER_COUPON_STATUS_LABELS[coupon.status ?? 'ACTIVE'],
      createdAt: coupon.createdAt ? formatPartnerBenefitDate(coupon.createdAt) : '-'
    }
  })

  const handleStoreManageButtonClick: React.MouseEventHandler<HTMLButtonElement> = () => {
    navigate('/admin/benefit-stores')
  }

  const handleAdminButtonClick: React.MouseEventHandler<HTMLButtonElement> = () => {
    navigate('/admin')
  }

  const handleCouponRegisterButtonClick: React.MouseEventHandler<HTMLButtonElement> = () => {
    navigate('/admin/benefit-coupon-form')
  }

  const handleEditCouponButtonClick =
    (couponId: number): React.MouseEventHandler<HTMLButtonElement> =>
    () => {
      navigate(`/admin/benefit-coupon-form?benefitCouponId=${couponId}`)
    }

  const handleDeleteCouponButtonClick =
    (storeId: number, couponId: number): React.MouseEventHandler<HTMLButtonElement> =>
    () => {
      setDeleteTargetCoupon({ storeId, couponId })
    }

  const handleDeleteDialogClose: React.MouseEventHandler<HTMLButtonElement> = () => {
    setDeleteTargetCoupon(null)
  }

  const handleDeleteDialogSubmit: React.MouseEventHandler<HTMLButtonElement> = async () => {
    if (!deleteTargetCoupon) return

    try {
      await deletePartnerCoupon(deleteTargetCoupon.storeId, deleteTargetCoupon.couponId)
    } catch {
      return
    } finally {
      setDeleteTargetCoupon(null)
    }
  }

  const columns: GridColDef<CouponTableRow>[] = [
    { field: 'storeName', headerName: '가게명', flex: 1, minWidth: 180 },
    { field: 'benefitContent', headerName: '혜택 내용', flex: 1.7, minWidth: 260 },
    { field: 'period', headerName: '쿠폰 기간', flex: 1, minWidth: 210 },
    {
      field: 'status',
      headerName: '상태',
      flex: 0.6,
      minWidth: 100,
      align: 'center',
      headerAlign: 'center',
      renderCell: (params: GridRenderCellParams<CouponTableRow>) => (
        <Chip
          label={params.value}
          size="small"
          color={params.value === '활성' ? 'success' : 'default'}
          variant="outlined"
        />
      )
    },
    { field: 'createdAt', headerName: '등록일', flex: 0.7, minWidth: 120 },
    {
      field: 'actions',
      headerName: '관리',
      flex: 0.9,
      minWidth: 170,
      sortable: false,
      filterable: false,
      renderCell: (params: GridRenderCellParams<CouponTableRow>) => (
        <Stack direction="row" spacing={1}>
          <Button variant="outlined" size="small" onClick={handleEditCouponButtonClick(params.row.id)}>
            수정
          </Button>
          <Button
            variant="outlined"
            color="error"
            size="small"
            onClick={handleDeleteCouponButtonClick(params.row.storeId, params.row.id)}
          >
            삭제
          </Button>
        </Stack>
      )
    }
  ]

  return (
    <>
      <Helmet>
        <title>등록된 쿠폰 관리 - KLUB</title>
      </Helmet>
      <PageTitleWrapper>
        <Stack direction={{ xs: 'column', md: 'row' }} justifyContent="space-between" spacing={2}>
          <Box>
            <Typography variant={isMobile ? 'h4' : 'h3'}>등록된 쿠폰 관리</Typography>
            <Typography color="text.secondary" sx={{ mt: 1 }}>
              등록된 쿠폰을 테이블에서 확인하고, 수정 시에는 등록 때 입력한 주요 항목을 한 번에 다시 편집할 수 있습니다.
            </Typography>
          </Box>
          <Stack direction="row" spacing={1}>
            <Button variant="contained" onClick={handleCouponRegisterButtonClick}>
              쿠폰 등록
            </Button>
            <Button variant="outlined" onClick={handleStoreManageButtonClick}>
              가게 목록 보기
            </Button>
            <Button variant="outlined" onClick={handleAdminButtonClick}>
              어드민 페이지
            </Button>
          </Stack>
        </Stack>
      </PageTitleWrapper>
      <Container maxWidth="xl">
        <Card sx={{ width: '100%', boxShadow: theme.header.boxShadow }}>
          <DataGrid
            autoHeight
            rows={couponRows}
            columns={columns}
            pageSizeOptions={[5, 10, 25]}
            initialState={{ pagination: { paginationModel: { pageSize: 10 } } }}
            disableRowSelectionOnClick
          />
        </Card>
      </Container>
      <ConfirmDialog
        open={deleteTargetCoupon !== null}
        handleClose={handleDeleteDialogClose}
        handleSubmit={handleDeleteDialogSubmit}
        confirmMessage={DEFAULT_DELETE_MESSAGE}
      />
    </>
  )
}

export default BenefitCouponManagePage
